#!/usr/bin/env node
// sw-sim.js — runs the service worker generated by the gateway in
// Node to reproduce/validate the offline cache behavior.
//
// The SW uses: self, caches, fetch, Request, Response, Blob,
// workbox (importScripts). We stub everything needed:
//  - caches: mini CacheStorage/Cache implementation (key = URL+method)
//  - fetch: backend controlled by the test
//  - importScripts/workbox: minimal stubs (registerRoute captures
//    the routes; ExpirationPlugin is a no-op that counts purges)
//
// Usage: node sw-sim.js <sw.js path> <test file>
// (the test file exports run({routes, caches, fetchCtrl}))
const fs = require('fs');
const vm = require('vm');

async function loadSW(swPath) {
  const code = fs.readFileSync(swPath, 'utf8');

  // ---- stubs ----
  const routes = [];
  const cacheStore = new Map(); // name -> Map(requestKey -> Response)
  const requestKey = (req) => req.method + ' ' + req.url;

  class Cache {
    constructor(name) { this.name = name; this.map = new Map(); }
    async match(req) {
      const hit = this.map.get(requestKey(req));
      return hit ? hit.clone() : undefined;
    }
    async put(req, resp) {
      if (req.method !== 'GET') {
        // like real Cache Storage: POSTs are not refused
        // but the key ignores the body (that's the bug we want to demonstrate)
      }
      this.map.set(requestKey(req), resp.clone());
    }
    async keys() { return [...this.map.keys()]; }
    async delete(req) { return this.map.delete(requestKey(req)); }
  }

  const caches = {
    async open(name) {
      if (!cacheStore.has(name)) cacheStore.set(name, new Cache(name));
      return cacheStore.get(name);
    },
    async keys() { return [...cacheStore.keys()]; },
    async delete(name) { return cacheStore.delete(name); },
    _store: cacheStore,
  };

  const swGlobals = {
    skipWaitingCalled: false,
    activated: false,
    deletedCaches: [],
  };

  const self = {
    addEventListener(ev, fn) {
      if (ev === 'activate') swGlobals._activate = fn;
    },
    skipWaiting() { swGlobals.skipWaitingCalled = true; return Promise.resolve(); },
    clients: { async claim() { return []; } },
    // navigator.onLine: the offline replay SW reads it to
    // short-circuit the fetch when the OS knows the network is down.
    // Mutable by tests: self.navigator.onLine = false.
    navigator: { onLine: true },
  };

  let backend = async () => new Response('default', { status: 404 });
  const fetchCtrl = {
    set(fn) { backend = fn; },
    calls: [],
  };
  const fetchFn = async (req, opts) => {
    fetchCtrl.calls.push(req);
    return backend(req, opts);
  };

  function importScripts() {}
  const workbox = {
    setConfig() {},
    routing: {
      // 3rd argument = required method ('GET' by default, like the
      // workbox Route constructor: a route without an explicit
      // method only matches GETs).
      registerRoute(match, handler, method) {
        routes.push({ match, handler, method: method || 'GET' });
      },
    },
    strategies: {
      // The strategies are objects with .handle({event, url,
      // request, params}) in workbox; the sim implements the minimal
      // real behavior expected by the generated routes:
      // NetworkOnly = direct fetch; NetworkFirst = network then
      // cache; StaleWhileRevalidate = cache then network in the
      // background; CacheFirst = cache then network.
      // cacheName/networkTimeoutSeconds are read from opts.
      NetworkFirst: class { constructor(opts) { this.opts = opts; }
        async handle({event, request, url}) {
          try {
            const resp = await fetchFn(request);
            if (resp.ok) {
              const c = await caches.open(this.opts.cacheName);
              event.waitUntil(c.put(request, resp.clone()));
              return resp;
            }
          } catch (e) { /* offline */ }
          const c = await caches.open(this.opts.cacheName);
          const hit = await c.match(request);
          if (hit) return hit;
          throw new TypeError('Failed to fetch');
        } },
      NetworkOnly: class { constructor(opts) { this.opts = opts; }
        async handle({event, request}) { return fetchFn(request); } },
      StaleWhileRevalidate: class { constructor(opts) { this.opts = opts; }
        async handle({event, request, url}) {
          const c = await caches.open(this.opts.cacheName);
          const hit = await c.match(request);
          const refresh = () => (async () => {
            try {
              const resp = await fetchFn(request);
              if (resp.ok) event.waitUntil(c.put(request, resp.clone()));
            } catch (e) { /* offline */ }
          })();
          if (hit) { event.waitUntil(refresh()); return hit; }
          const resp = await fetchFn(request);
          if (resp.ok) event.waitUntil(c.put(request, resp.clone()));
          return resp;
        } },
      CacheFirst: class { constructor(opts) { this.opts = opts; }
        async handle({event, request, url}) {
          const c = await caches.open(this.opts.cacheName);
          const hit = await c.match(request);
          if (hit) return hit;
          return fetchFn(request);
        } },
    },
    expiration: {
      ExpirationPlugin: class {
        constructor(opts) { this.opts = opts; swGlobals.expiration = this; }
        async cacheDidUpdate() { swGlobals.purges = (swGlobals.purges || 0) + 1; }
      },
    },
  };

  const ctx = vm.createContext({
    self, importScripts, workbox, caches, fetch: fetchFn,
    Request, Response, Blob, ReadableStream, TextEncoder, TextDecoder,
    URL, console, Promise, crypto: require('crypto').webcrypto,
    setTimeout, clearTimeout, setInterval, clearInterval,
    AbortController,
  });
  vm.runInContext(code, ctx, { filename: swPath });

  return { routes, caches, fetchCtrl, fetch: fetchFn, swGlobals, self: ctx.self };
}

// runs the route matching the request, as the browser would
async function dispatch(routes, req) {
  for (const r of routes) {
    // workbox: the route's required method must match
    if ((r.method || 'GET') !== req.method) continue;
    const url = new URL(req.url);
    let ok = false;
    try { ok = r.match({ request: req, url, event: { request: req, waitUntil: () => {} } }); }
    catch (e) { ok = false; }
    if (ok) {
      // waitUntil: captures the promises like a real SW (the handler
      // must pass its background work through it, otherwise the
      // browser suspends the SW before completion — a bug the sim
      // must be able to detect)
      const extended = [];
      const event = {
        request: req,
        waitUntil: (p) => extended.push(Promise.resolve(p)),
      };
      const handlerFn = typeof r.handler === "function"
        ? r.handler
        : () => r.handler.handle({ event, request: req, url: new URL(req.url) });
      const result = await handlerFn({ event, request: req });
      event._extended = extended;
      return result;
    }
  }
  throw new Error('no route matched ' + req.url);
}

module.exports = { loadSW, dispatch };

// ---- CLI: quick reproduction of the Obelisque bug ----
if (require.main === module) {
  const swPath = process.argv[2] || './sw.js';
  console.log('SIM BOOT', swPath);
  (async () => {
    const { routes, caches, fetchCtrl } = await loadSW(swPath);

    // backend: SSE stream that never closes (keep-alive SSE),
    // different response per request body
    fetchCtrl.set(async (req) => {
      const body = await req.clone().text();
      const enc = new TextEncoder();
      const stream = new ReadableStream({
        start(c) {
          c.enqueue(enc.encode('data: {"poesie":"' + body.slice(0, 40) + '"}\n\n'));
          if (process.env.SSE_CLOSE === '1') c.close(); // closing backend
          // otherwise: the connection stays open (keep-alive SSE)
        },
      });
      return new Response(stream, { status: 200, headers: { 'Content-Type': 'text/event-stream' } });
    });

    // 1. Obelisque segmentation — with timeout: if the SSE stream
    // without closure blocks consumption, we document it (that's the
    // targeted bug) and move on to inspecting the caches.
    const req1 = new Request('https://vers.cladone.com/api/process_stream', {
      method: 'POST', body: 'poesie=Obelisque',
    });
    const resp1 = await dispatch(routes, req1);
    const consumed = await Promise.race([
      resp1.clone().text().then(() => true),
      new Promise((r) => setTimeout(() => r(false), 3000)),
    ]);
    if (!consumed) {
      console.error('STREAM-NEVER-ENDS: consuming the SSE stream (without server closure) never ends — storeCompleteResponse cannot reach done => nothing is ever cached');
    }
    await new Promise((r) => setTimeout(r, 100));

    // 2. segmentation of another poem
    const req2 = new Request('https://vers.cladone.com/api/process_stream', {
      method: 'POST', body: 'poesie=Antigone',
    });
    const resp2 = await dispatch(routes, req2);
    const consumed2 = await Promise.race([resp2.clone().text().then(() => true), new Promise((r) => setTimeout(() => r(false), 3000))]);
    if (!consumed2) console.error("STREAM-NEVER-ENDS (2nd segmentation)");
    await new Promise((r) => setTimeout(r, 100));

    // 3. cache inspection
    const names = await caches.keys();
    console.log('caches present:', names); console.error('DEBUG names.length=' + names.length);
    for (const name of names.filter((n) => n.includes('api'))) {
      const c = await caches.open(name);
      const keys = await c.keys();
      console.log(`cache ${name}: ${keys.length} entry(ies) ->`, keys);
    }
    const anyApi = names.find((n) => n.includes('api'));
    if (!anyApi) {
      console.log('\nRESULT: NO API cache — bug reproduced (SSE stream without closure + non-cacheable POST request => nothing is stored)');
      process.stdout.write('EXIT-2\n'); process.exit(2);
    }
    const c = await caches.open(anyApi);
    const n = (await c.keys()).length;
    console.log(`\nRESULT: ${n} entry(ies) in ${anyApi}`);
    if (n === 0) { console.log('=> bug reproduced: nothing cached'); process.stdout.write('EXIT-2\n'); process.exit(2); }
    if (n === 1) {
      const hit = await c.match(new Request('https://vers.cladone.com/api/process_stream', { method: 'POST', body: 'poesie=Obelisque' }));
      console.log('Obelisque match:', hit ? 'YES (but body-blind key: risk of replaying another poem!)' : 'no');
      console.log('=> keys overwrite each other (body ignored by Cache Storage) => key bug reproduced');
      process.stdout.write('EXIT-3\n'); process.exit(3);
    }
    process.stdout.write('EXIT-0\n'); process.exit(0);
  })().catch((e) => { console.error(e); process.exit(1); });
}